parameters.jsCode:
const tz = $json.timezone || 'America/Mexico_City';
const start = DateTime.fromISO($json.starts_at).setZone(tz);
const humanLabel = start.setLocale('es').toFormat("cccc d 'de' LLLL 'a las' h:mm a");
const contact = $json.contacts || {};
const service = $json.services || {};

return {
  json: {
    id: $json.id,
    google_meet_url: $json.google_meet_url || null,
    humanLabel,
    clientName: contact.full_name || 'Cliente',
    clientEmail: contact.email || '',
    clientCompany: contact.company_name || '',
    serviceName: service.name || 'No especificado',
  },
};

